/* Extends retains detached getter results and unpublished prototypes through setter GC/errors. */
#define FVM_VALUE_CALLBACKS_FIXTURE_ONLY
#include "execution_value_callbacks.cpp"
#include "../src/core/runtime.hpp"
static unsigned gets,sets,mode;
static FVM_Object *expected_super;
static FVM_Result read_none(FVM_Context *,const FVM_ScriptFrame *,FVM_Value *out,void *){fvm_value_undefined(out);return FVM_OK;}
static FVM_Result super_get(FVM_Context *c,const FVM_ScriptFrame *frame,FVM_Value *out,void *)
{int removed=0;++gets;assert(fvm_object_delete(c,frame->receiver,"prototype",&removed)==FVM_OK && removed && fvm_gc_collect(c,0)==FVM_OK);if(mode==1){fvm_value_number(out,77);return fvm_exception_raise(c,out);}fvm_value_undefined(out);out->type=FVM_VALUE_OBJECT;out->object=frame->capture;return FVM_OK;}
static FVM_Result sub_put(FVM_Context *c,const FVM_ScriptFrame *frame,FVM_Value *out,void *)
{FVM_Value parent,ctor,v;unsigned flags=0;++sets;assert(frame->argc==1 && frame->argv[0].type==FVM_VALUE_OBJECT && fvm_gc_collect(c,0)==FVM_OK && fvm_object_get(c,frame->argv[0].object,"__proto__",&parent)==FVM_OK && parent.type==FVM_VALUE_OBJECT && fvm_object_get(c,parent.object,"alive",&v)==FVM_OK && v.number==17 && fvm_object_get(c,frame->argv[0].object,"constructor",&ctor)==FVM_OK && ctor.object==expected_super && fvm_object_property_flags(c,frame->argv[0].object,"constructor",&flags)==FVM_OK && flags==FVM_PROPERTY_DONT_ENUM && fvm_set_global(c,"published",frame->argv)==FVM_OK);if(mode==2){fvm_value_number(out,88);return fvm_exception_raise(c,out);}fvm_value_undefined(out);return FVM_OK;}
static FVM_Object *body_function(FVM_Context *c,FVM_ScriptBody body,FVM_Object *capture){FVM_Object *fn=0;const unsigned char code[]={0};assert(fvm_function_create_avm1(c,code,sizeof(code),0,0,0,&fn)==FVM_OK && fvm_function_set_body(c,fn,body,0,capture)==FVM_OK);return fn;}
static void property(FVM_Context *c,FVM_Object *object,FVM_Object *get,FVM_Object *put){FVM_Value args[3],out;fvm_value_string(args,"prototype");fvm_value_undefined(args+1);args[1].type=FVM_VALUE_OBJECT;args[1].object=get;fvm_value_undefined(args+2);if(put){args[2].type=FVM_VALUE_OBJECT;args[2].object=put;}else args[2].type=FVM_VALUE_NULL;assert(fvm_object_call(c,object,"addProperty",3,args,&out)==FVM_OK && out.boolean);}
int main(){FVM_Config cfg;FVM_Runtime *rt=0;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK);for(unsigned version=4;version<=8;++version)for(mode=0;mode<3;++mode){FVM_Context *c=0;FVM_Object *sub=0,*super=0,*parent=0;assert(fvm_context_create(rt,&c)==FVM_OK);unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};swf[3]=(unsigned char)version;assert(fvm_load_memory(c,swf,sizeof(swf))==FVM_OK && fvm_standard_install(c)==FVM_OK && fvm_construct(c,"Object",0,0,&sub)==FVM_OK && fvm_construct(c,"Object",0,0,&super)==FVM_OK && fvm_object_create(c,&parent)==FVM_OK);FVM_Value a,b,v;fvm_value_number(&v,17);assert(fvm_object_set(c,parent,"alive",&v)==FVM_OK);property(c,super,body_function(c,super_get,parent),0);property(c,sub,body_function(c,read_none,0),body_function(c,sub_put,0));fvm_value_undefined(&a);a.type=FVM_VALUE_OBJECT;a.object=sub;b=a;b.object=super;expected_super=super;unsigned before=sets;FVM_Result r=fvm_exec_extends(c,&a,&b);assert(!c->gc_frames);if(mode){assert(r==FVM_EXCEPTION && sets==before+(mode==2?1U:0U) && fvm_exception_clear(c)==FVM_OK);}else assert(r==FVM_OK && sets==before+1);if(mode!=1)assert(fvm_gc_collect(c,0)==FVM_OK && fvm_get_global(c,"published",&v)==FVM_OK && v.type==FVM_VALUE_OBJECT);fvm_context_destroy(c);}assert(gets==15 && sets==10);fvm_runtime_destroy(rt);return 0;}
